#!/usr/bin/env python3
from __future__ import annotations
import pathlib,sys
if len(sys.argv)!=3: raise SystemExit('usage: gen-b300-grand-firstpass-stages.py INPUT.sh OUTPUT.sh')
src=pathlib.Path(sys.argv[1]); out=pathlib.Path(sys.argv[2]); s=src.read_text()
def rep(old:str,new:str,label:str)->None:
    global s
    if new in s: return
    n=s.count(old)
    if n!=1: raise SystemExit(f'{label}: expected one anchor, got {n}')
    s=s.replace(old,new,1)
rep('source "$(dirname -- "${BASH_SOURCE[0]}")/../lib/common.sh"','source "${ONEESAN_ROOT:?ONEESAN_ROOT must be exported}/scripts/lib/common.sh"','common source')
anchor='RUN_STAGER="${RUN_STAGER:-1}"\n'; rep(anchor,anchor+'RUN_STAGES="${RUN_STAGES:-1}"\n','RUN_STAGES')
anchor='STAGER_BLOCK_POLICY_LIST="${STAGER_BLOCK_POLICY_LIST:-default cg cs}"\n'
rep(anchor,anchor+'''STAGES_MIN_SPEEDUP="${STAGES_MIN_SPEEDUP:-1.002}"
STAGES_PAIR_L2_LIST="${STAGES_PAIR_L2_LIST:-0 64 128 256}"
STAGES_BLOCK_L2_LIST="${STAGES_BLOCK_L2_LIST:-0 64 128 256}"
''','Stage-S knobs')
rep('for x in REBUILD_BUCKETS RUN_NEXTSELF_STAGE RUN_HYBRID_STAGE RUN_HYBRID_NS_STAGE RUN_STAGEI RUN_STAGEJ RUN_STAGEK RUN_STAGEL RUN_STAGEM RUN_STAGEN RUN_STAGEO RUN_STAGEP RUN_STAGEQ RUN_STAGER; do','for x in REBUILD_BUCKETS RUN_NEXTSELF_STAGE RUN_HYBRID_STAGE RUN_HYBRID_NS_STAGE RUN_STAGEI RUN_STAGEJ RUN_STAGEK RUN_STAGEL RUN_STAGEM RUN_STAGEN RUN_STAGEO RUN_STAGEP RUN_STAGEQ RUN_STAGER RUN_STAGES; do','boolean validation')
anchor='STAGER_BLOCK_POLICY_LIST="$(normalize_load_policies "$STAGER_BLOCK_POLICY_LIST")"\n'
rep(anchor,anchor+'''STAGES_PAIR_L2_LIST="$(normalize_l2_sizes "$STAGES_PAIR_L2_LIST")"
STAGES_BLOCK_L2_LIST="$(normalize_l2_sizes "$STAGES_BLOCK_L2_LIST")"
case " $STAGES_PAIR_L2_LIST " in *' 0 '*) ;; *) echo 'STAGES_PAIR_L2_LIST must include 0 baseline' >&2; exit 2;; esac
case " $STAGES_BLOCK_L2_LIST " in *' 0 '*) ;; *) echo 'STAGES_BLOCK_L2_LIST must include 0 baseline' >&2; exit 2;; esac
''','Stage-S L2 normalization')
old='python3 - "$NEXTSELF_MIN_SPEEDUP" "$HYBRID_MIN_SPEEDUP" "$HYBRID_NS_MIN_SPEEDUP" "$STAGEI_MIN_SPEEDUP" "$STAGEJ_MIN_SPEEDUP" "$STAGEK_MIN_SPEEDUP" "$STAGEL_MIN_SPEEDUP" "$STAGEM_MIN_SPEEDUP" "$STAGEN_MIN_SPEEDUP" "$STAGEO_MIN_SPEEDUP" "$STAGEP_MIN_SPEEDUP" "$STAGEQ_MIN_SPEEDUP" "$STAGER_MIN_SPEEDUP" <<\'PY\'\nimport sys\nnames=(\'NEXTSELF_MIN_SPEEDUP\',\'HYBRID_MIN_SPEEDUP\',\'HYBRID_NS_MIN_SPEEDUP\',\'STAGEI_MIN_SPEEDUP\',\'STAGEJ_MIN_SPEEDUP\',\'STAGEK_MIN_SPEEDUP\',\'STAGEL_MIN_SPEEDUP\',\'STAGEM_MIN_SPEEDUP\',\'STAGEN_MIN_SPEEDUP\',\'STAGEO_MIN_SPEEDUP\',\'STAGEP_MIN_SPEEDUP\',\'STAGEQ_MIN_SPEEDUP\',\'STAGER_MIN_SPEEDUP\')\nfor name,v in zip(names,map(float,sys.argv[1:])):\n    if v < 1.0: raise SystemExit(f\'{name} must be >=1\')\nPY'
new='python3 - "$NEXTSELF_MIN_SPEEDUP" "$HYBRID_MIN_SPEEDUP" "$HYBRID_NS_MIN_SPEEDUP" "$STAGEI_MIN_SPEEDUP" "$STAGEJ_MIN_SPEEDUP" "$STAGEK_MIN_SPEEDUP" "$STAGEL_MIN_SPEEDUP" "$STAGEM_MIN_SPEEDUP" "$STAGEN_MIN_SPEEDUP" "$STAGEO_MIN_SPEEDUP" "$STAGEP_MIN_SPEEDUP" "$STAGEQ_MIN_SPEEDUP" "$STAGER_MIN_SPEEDUP" "$STAGES_MIN_SPEEDUP" <<\'PY\'\nimport sys\nnames=(\'NEXTSELF_MIN_SPEEDUP\',\'HYBRID_MIN_SPEEDUP\',\'HYBRID_NS_MIN_SPEEDUP\',\'STAGEI_MIN_SPEEDUP\',\'STAGEJ_MIN_SPEEDUP\',\'STAGEK_MIN_SPEEDUP\',\'STAGEL_MIN_SPEEDUP\',\'STAGEM_MIN_SPEEDUP\',\'STAGEN_MIN_SPEEDUP\',\'STAGEO_MIN_SPEEDUP\',\'STAGEP_MIN_SPEEDUP\',\'STAGEQ_MIN_SPEEDUP\',\'STAGER_MIN_SPEEDUP\',\'STAGES_MIN_SPEEDUP\')\nfor name,v in zip(names,map(float,sys.argv[1:])):\n    if v < 1.0: raise SystemExit(f\'{name} must be >=1\')\nPY'
rep(old,new,'speed validation')
anchor="  printf 'stager_block_policy_list=%s\\n' \"$STAGER_BLOCK_POLICY_LIST\"\n"
rep(anchor,anchor+"  printf 'run_stages=%s\\n' \"$RUN_STAGES\"\n  printf 'stages_min_speedup=%s\\n' \"$STAGES_MIN_SPEEDUP\"\n  printf 'stages_pair_l2_list=%s\\n' \"$STAGES_PAIR_L2_LIST\"\n  printf 'stages_block_l2_list=%s\\n' \"$STAGES_BLOCK_L2_LIST\"\n",'meta Stage S')
anchor='bash "$ONEESAN_ROOT/scripts/bench/b300-grand-stager-contract-preflight.sh"\n'
rep(anchor,anchor+'bash "$ONEESAN_ROOT/scripts/bench/b300-stages-preflight.sh"\nbash "$ONEESAN_ROOT/scripts/bench/b300-grand-stages-contract-preflight.sh"\n','Stage-S GPU-free preflight')
rep(' r_pair=[$STAGER_PAIR_POLICY_LIST] r_block=[$STAGER_BLOCK_POLICY_LIST] ===',' r_pair=[$STAGER_PAIR_POLICY_LIST] r_block=[$STAGER_BLOCK_POLICY_LIST] s_pair_l2=[$STAGES_PAIR_L2_LIST] s_block_l2=[$STAGES_BLOCK_L2_LIST] ===','Stage-S banner')
rep('  RUN_STAGEI="$RUN_STAGEI" RUN_STAGEJ="$RUN_STAGEJ" RUN_STAGEK="$RUN_STAGEK" RUN_STAGEL="$RUN_STAGEL" RUN_STAGEM="$RUN_STAGEM" RUN_STAGEN="$RUN_STAGEN" RUN_STAGEO="$RUN_STAGEO" RUN_STAGEP="$RUN_STAGEP" RUN_STAGEQ="$RUN_STAGEQ" RUN_STAGER="$RUN_STAGER" \\\n','  RUN_STAGEI="$RUN_STAGEI" RUN_STAGEJ="$RUN_STAGEJ" RUN_STAGEK="$RUN_STAGEK" RUN_STAGEL="$RUN_STAGEL" RUN_STAGEM="$RUN_STAGEM" RUN_STAGEN="$RUN_STAGEN" RUN_STAGEO="$RUN_STAGEO" RUN_STAGEP="$RUN_STAGEP" RUN_STAGEQ="$RUN_STAGEQ" RUN_STAGER="$RUN_STAGER" RUN_STAGES="$RUN_STAGES" \\\n','selector run flags')
rep('  STAGEL_MIN_SPEEDUP="$STAGEL_MIN_SPEEDUP" STAGEM_MIN_SPEEDUP="$STAGEM_MIN_SPEEDUP" STAGEN_MIN_SPEEDUP="$STAGEN_MIN_SPEEDUP" STAGEO_MIN_SPEEDUP="$STAGEO_MIN_SPEEDUP" STAGEP_MIN_SPEEDUP="$STAGEP_MIN_SPEEDUP" STAGEQ_MIN_SPEEDUP="$STAGEQ_MIN_SPEEDUP" STAGER_MIN_SPEEDUP="$STAGER_MIN_SPEEDUP" \\\n','  STAGEL_MIN_SPEEDUP="$STAGEL_MIN_SPEEDUP" STAGEM_MIN_SPEEDUP="$STAGEM_MIN_SPEEDUP" STAGEN_MIN_SPEEDUP="$STAGEN_MIN_SPEEDUP" STAGEO_MIN_SPEEDUP="$STAGEO_MIN_SPEEDUP" STAGEP_MIN_SPEEDUP="$STAGEP_MIN_SPEEDUP" STAGEQ_MIN_SPEEDUP="$STAGEQ_MIN_SPEEDUP" STAGER_MIN_SPEEDUP="$STAGER_MIN_SPEEDUP" STAGES_MIN_SPEEDUP="$STAGES_MIN_SPEEDUP" \\\n','selector speed flags')
rep('  STAGEL_GUARD_LIST="$STAGEL_GUARD_LIST" STAGEM_POLICY_LIST="$STAGEM_POLICY_LIST" STAGEN_PAIR_POLICY_LIST="$STAGEN_PAIR_POLICY_LIST" STAGEN_BLOCK_POLICY_LIST="$STAGEN_BLOCK_POLICY_LIST" STAGEO_PAIR_L2_LIST="$STAGEO_PAIR_L2_LIST" STAGEO_BLOCK_L2_LIST="$STAGEO_BLOCK_L2_LIST" STAGEP_MATE_L2_LIST="$STAGEP_MATE_L2_LIST" STAGEQ_PAIR_L2_LIST="$STAGEQ_PAIR_L2_LIST" STAGEQ_BLOCK_L2_LIST="$STAGEQ_BLOCK_L2_LIST" STAGER_PAIR_POLICY_LIST="$STAGER_PAIR_POLICY_LIST" STAGER_BLOCK_POLICY_LIST="$STAGER_BLOCK_POLICY_LIST" \\\n  PREFIX="$PREFIX" bash "$ONEESAN_ROOT/scripts/run/b300x8-joint-nextself-hybrid8-select-stager.sh" 27 "$@" \\\n','  STAGEL_GUARD_LIST="$STAGEL_GUARD_LIST" STAGEM_POLICY_LIST="$STAGEM_POLICY_LIST" STAGEN_PAIR_POLICY_LIST="$STAGEN_PAIR_POLICY_LIST" STAGEN_BLOCK_POLICY_LIST="$STAGEN_BLOCK_POLICY_LIST" STAGEO_PAIR_L2_LIST="$STAGEO_PAIR_L2_LIST" STAGEO_BLOCK_L2_LIST="$STAGEO_BLOCK_L2_LIST" STAGEP_MATE_L2_LIST="$STAGEP_MATE_L2_LIST" STAGEQ_PAIR_L2_LIST="$STAGEQ_PAIR_L2_LIST" STAGEQ_BLOCK_L2_LIST="$STAGEQ_BLOCK_L2_LIST" STAGER_PAIR_POLICY_LIST="$STAGER_PAIR_POLICY_LIST" STAGER_BLOCK_POLICY_LIST="$STAGER_BLOCK_POLICY_LIST" STAGES_PAIR_L2_LIST="$STAGES_PAIR_L2_LIST" STAGES_BLOCK_L2_LIST="$STAGES_BLOCK_L2_LIST" \\\n  PREFIX="$PREFIX" bash "$ONEESAN_ROOT/scripts/run/b300x8-joint-nextself-hybrid8-select-stages.sh" 27 "$@" \\\n','Stage-S selector entrypoint')
rep('   "${B300_GRAND_STAGEM_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGEN_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGEO_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGEP_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGEQ_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGER_INTEGRATED:-0}" == 1 && \\\n   "${B300_GRAND_STAGEI_NAMESPACE_ISOLATED:-0}" == 1 && "${B300_GRAND_COMPLETE_PRIME_RACES:-0}" == 1 ]] || {\n  echo \'grand Stage-I/J/K/L/M/N/O/P/Q/R single-race provenance markers missing\' >&2; exit 4;','   "${B300_GRAND_STAGEM_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGEN_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGEO_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGEP_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGEQ_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGER_INTEGRATED:-0}" == 1 && "${B300_GRAND_STAGES_INTEGRATED:-0}" == 1 && \\\n   "${B300_GRAND_STAGEI_NAMESPACE_ISOLATED:-0}" == 1 && "${B300_GRAND_COMPLETE_PRIME_RACES:-0}" == 1 ]] || {\n  echo \'grand Stage-I/J/K/L/M/N/O/P/Q/R/S single-race provenance markers missing\' >&2; exit 4;','summary provenance')
anchor="  printf 'B300_GRAND_SELECTED_COMPLETE_PRIME_RACES=1\\n'\n"
rep(anchor,'''  printf 'B300_GRAND_SELECTED_STAGES_ENABLED=%q\n' "$RUN_STAGES"
  printf 'B300_GRAND_SELECTED_STAGES_MIN_SPEEDUP=%q\n' "$STAGES_MIN_SPEEDUP"
  printf 'B300_GRAND_SELECTED_STAGES_ACCEPTED=%q\n' "${B300_GRAND_STAGES_OK:-0}"
  printf 'B300_GRAND_SELECTED_STAGES_STAGER_UPSTREAM_KIND=%q\n' "${B300_GRAND_STAGES_STAGER_UPSTREAM_KIND:-}"
  printf 'B300_GRAND_SELECTED_STAGES_LOW_PAIR_POLICY=%q\n' "${B300_GRAND_STAGES_LOW_PAIR_POLICY:-default}"
  printf 'B300_GRAND_SELECTED_STAGES_LOW_BLOCK_POLICY=%q\n' "${B300_GRAND_STAGES_LOW_BLOCK_POLICY:-default}"
  printf 'B300_GRAND_SELECTED_STAGES_HIGH_PAIR_POLICY=%q\n' "${B300_GRAND_STAGES_HIGH_PAIR_POLICY:-default}"
  printf 'B300_GRAND_SELECTED_STAGES_HIGH_BLOCK_POLICY=%q\n' "${B300_GRAND_STAGES_HIGH_BLOCK_POLICY:-default}"
  printf 'B300_GRAND_SELECTED_STAGES_HIGH_PAIR_L2_BYTES=%q\n' "${B300_GRAND_STAGES_HIGH_PAIR_L2_BYTES:-0}"
  printf 'B300_GRAND_SELECTED_STAGES_HIGH_BLOCK_L2_BYTES=%q\n' "${B300_GRAND_STAGES_HIGH_BLOCK_L2_BYTES:-0}"
  printf 'B300_GRAND_SELECTED_STAGES_PAIR_L2_BYTES=%q\n' "${B300_GRAND_STAGES_PAIR_L2_BYTES:-0}"
  printf 'B300_GRAND_SELECTED_STAGES_BLOCK_L2_BYTES=%q\n' "${B300_GRAND_STAGES_BLOCK_L2_BYTES:-0}"
  printf 'B300_GRAND_SELECTED_STAGES_STAGED_SPEEDUP=%q\n' "${B300_GRAND_STAGES_STAGED_SPEEDUP:-1.0}"
  printf 'B300_GRAND_SELECTED_STAGES_SEARCH_PAIR_L2=%q\n' "$STAGES_PAIR_L2_LIST"
  printf 'B300_GRAND_SELECTED_STAGES_SEARCH_BLOCK_L2=%q\n' "$STAGES_BLOCK_L2_LIST"
'''+anchor,'selected Stage S')
for marker in ('RUN_STAGES=','STAGES_PAIR_L2_LIST=','STAGES_BLOCK_L2_LIST=','b300x8-joint-nextself-hybrid8-select-stages.sh','B300_GRAND_SELECTED_STAGES_ACCEPTED','B300_GRAND_STAGES_INTEGRATED'):
    if marker not in s: raise SystemExit('missing generated Stage-S firstpass artifact: '+marker)
out.parent.mkdir(parents=True,exist_ok=True); out.write_text(s)
print(f'generated {out} from {src}: b300_grand_firstpass_stages=1 selected_schema_compatible=3 single_complete_prime=1')
